<?php
use AISkillsHub\Core\Discovery\Frontend as Discovery;
use AISkillsHub\Core\Discovery\RankingPolicy;
use AISkillsHub\Core\Frontend\View;
defined( 'ABSPATH' ) || exit;
$context = Discovery::context(); $locale = $context['locale']; $data = $context['data']; $route = $data['route']; $filters = $data['filters'] ?? array(); $params = $data['params'] ?? array(); $topic = $data['topic'] ?? array(); $result = $data['result'] ?? array();
$navigation = array_merge( Discovery::RANKINGS, array( 'editors-picks', 'use-cases', 'platforms' ) );
get_header();
?>
<main id="main" class="discovery-page">
<div class="aish-container">
	<nav class="aish-breadcrumbs" aria-label="<?php echo esc_attr( 'zh_CN' === $locale ? '面包屑导航' : 'Breadcrumbs' ); ?>"><ol><li><a href="<?php echo esc_url( View::url( 'home', array(), $locale ) ); ?>"><?php echo esc_html( Discovery::t( 'home', $locale ) ); ?></a></li><li><?php if ( $topic ) : ?><a href="<?php echo esc_url( Discovery::link( $route, $locale ) ); ?>"><?php echo esc_html( Discovery::t( $route, $locale ) ); ?></a><?php else : ?><span aria-current="page"><?php echo esc_html( Discovery::t( $route, $locale ) ); ?></span><?php endif; ?></li><?php if ( $topic ) : ?><li><span aria-current="page"><?php echo esc_html( $data['discovery_title'] ); ?></span></li><?php endif; ?></ol></nav>
	<nav class="discovery-navigation" aria-label="<?php echo esc_attr( Discovery::t( 'discover', $locale ) ); ?>"><?php foreach ( $navigation as $target ) : ?><a href="<?php echo esc_url( Discovery::link( $target, $locale ) ); ?>" <?php echo $target === $route || ( 'editors-picks' === $target && 'collections' === $route ) ? 'aria-current="page"' : ''; ?>><?php echo esc_html( Discovery::t( $target, $locale ) ); ?></a><?php endforeach; ?></nav>
	<header class="discovery-intro"><h1><?php echo esc_html( $data['discovery_title'] ?? Discovery::t( 404 === $context['status'] ? 'not-found' : 'error', $locale ) ); ?></h1><?php if ( ! $context['error'] ) : ?><p><?php echo esc_html( wp_strip_all_tags( $topic['description'] ?? Discovery::t( 'intro', $locale ) ) ); ?></p><?php endif; ?></header>
	<?php if ( $context['error'] ) : ?><div class="discovery-notice" role="status"><p><?php echo esc_html( Discovery::t( 404 === $context['status'] ? 'not-found' : 'error', $locale ) ); ?></p><a href="<?php echo esc_url( View::url( 'skills', array(), $locale ) ); ?>"><?php echo esc_html( View::t( 'detail_browse_skills' ) ); ?></a></div>
	<?php else : ?>
		<?php if ( 'collections' === $route ) { if ( $topic ) { do_action( 'aish_collection_bundle_notice', (int) $topic['id'], $locale ); } else { do_action( 'aish_collection_bundle_directory', $locale ); } } ?>
		<?php if ( ! empty( $topic['evidence_url'] ) ) : ?><p><a class="text-link" href="<?php echo esc_url( $topic['evidence_url'] ); ?>" rel="noopener noreferrer nofollow"><?php echo esc_html( Discovery::t( 'platform-evidence', $locale ) ); ?></a></p><?php endif; ?>
		<?php if ( isset( $data['topics'] ) ) : ?>
			<?php if ( $data['topics'] ) : ?><div class="discovery-grid"><?php foreach ( $data['topics'] as $item ) { get_template_part( 'templates/discovery/topic', null, array( 'topic' => $item, 'locale' => $locale, 'route' => 'editors-picks' === $route ? 'collections' : $route ) ); } ?></div><?php else : ?><div class="discovery-empty"><h2><?php echo esc_html( Discovery::t( 'empty', $locale ) ); ?></h2><p><?php echo esc_html( Discovery::t( 'empty-help', $locale ) ); ?></p></div><?php endif; ?>
		<?php else : ?>
			<?php if ( in_array( $route, Discovery::RANKINGS, true ) ) : ?><aside class="discovery-method" aria-label="<?php echo esc_attr( 'zh_CN' === $locale ? '统计口径' : 'Ranking methodology' ); ?>"><p><?php echo esc_html( Discovery::t( 'method.' . $route, $locale ) ); ?></p>
				<?php if ( in_array( $route, array( 'trending', 'most-viewed' ), true ) ) : ?><p><?php echo esc_html( ( 'zh_CN' === $locale ? 'UTC 完整天数：' : 'Completed UTC days: ' ) . ( $result['coverage']['window_days'] ?? 7 ) . ' · ' . ( $result['coverage']['through'] ?? '' ) ); ?></p><p><?php echo esc_html( ! empty( $result['coverage']['views_started_at'] ) ? Discovery::t( 'coverage', $locale ) . ' ' . View::date( $result['coverage']['views_started_at'] ) : Discovery::t( 'no-coverage', $locale ) ); ?></p><?php endif; ?>
				<?php if ( 'trending' === $route ) : ?><p><a class="text-link" href="<?php echo esc_url( Discovery::link( 'recently-added', $locale ) ); ?>"><?php echo esc_html( Discovery::t( 'recently-added', $locale ) ); ?> →</a></p><?php endif; ?><?php if ( 'top-rated' === $route ) : ?><p><?php echo esc_html( ( 'zh_CN' === $locale ? '正式排名最低评价数量：' : 'Minimum approved reviews for ranking: ' ) . RankingPolicy::MIN_REVIEWS ); ?></p><?php endif; ?>
			</aside><?php endif; ?>
			<form method="get" action="<?php echo esc_url( Discovery::link( $route, $locale, array_filter( $params ) ) ); ?>" class="discovery-filters" x-data="{ submitting: false }" @submit="submitting = true" :aria-busy="submitting">
				<div class="form-field discovery-search"><label for="discovery-query" class="field-label"><?php echo esc_html( View::t( 'search.label' ) ); ?></label><input class="field-input" id="discovery-query" type="search" name="q" maxlength="100" value="<?php echo esc_attr( $filters['q'] ?? '' ); ?>"></div>
				<?php foreach ( array( 'category' => 'categories', 'tag' => 'tags', 'platform' => 'platforms' ) as $filter => $field ) : if ( 'platforms' === $route && $topic && 'platform' === $filter ) { continue; } ?><div class="form-field"><label class="field-label" for="discovery-<?php echo esc_attr( $filter ); ?>"><?php echo esc_html( View::t( 'filter.' . $filter ) ); ?></label><select class="field-input" name="<?php echo esc_attr( $filter ); ?>" id="discovery-<?php echo esc_attr( $filter ); ?>"><option value=""><?php echo esc_html( View::t( 'filter.all.' . $filter ) ); ?></option><?php foreach ( $data[ $field ] ?? array() as $option ) : ?><option value="<?php echo esc_attr( $option['slug'] ); ?>" <?php selected( $filters[ $filter ] ?? '', $option['slug'] ); ?>><?php echo esc_html( View::termLabel( $option, $data[ $field ] ?? array() ) ); ?></option><?php endforeach; ?><?php $selectedFilter = $filters[ $filter ] ?? ''; if ( $selectedFilter && ! in_array( $selectedFilter, array_column( $data[ $field ] ?? array(), 'slug' ), true ) ) : ?><option selected value="<?php echo esc_attr( $selectedFilter ); ?>"><?php echo esc_html( $selectedFilter ); ?></option><?php endif; ?></select></div><?php endforeach; ?>
				<?php if ( 'most-viewed' === $route ) : ?><div class="form-field"><label class="field-label" for="discovery-window"><?php echo esc_html( Discovery::t( 'window', $locale ) ); ?></label><select class="field-input" id="discovery-window" name="window"><?php foreach ( array( 7, 30 ) as $days ) : ?><option value="<?php echo $days; ?>" <?php selected( $filters['window'] ?? 7, $days ); ?>><?php echo esc_html( Discovery::t( 'days' . $days, $locale ) ); ?></option><?php endforeach; ?></select></div><?php endif; ?>
				<div class="discovery-filter-actions"><button class="button button-primary" type="submit"><span x-show="!submitting"><?php echo esc_html( View::t( 'search.action' ) ); ?></span><span x-cloak x-show="submitting"><?php echo esc_html( View::t( 'search.loading' ) ); ?></span></button><a href="<?php echo esc_url( Discovery::link( $route, $locale, array_filter( $params ) ) ); ?>"><?php echo esc_html( View::t( 'filter.reset' ) ); ?></a></div>
				<p class="discovery-filter-note"><?php echo esc_html( '* ' . Discovery::t( 'translation-missing', $locale ) ); ?></p>
			</form>
			<div class="results-heading"><h2><?php echo esc_html( Discovery::t( 'results', $locale ) ); ?><span><?php echo esc_html( number_format_i18n( $result['total'] ?? 0 ) ); ?></span></h2><p><?php echo esc_html( View::t( 'listing.locale_note' ) ); ?></p></div>
			<?php if ( ! empty( $result['items'] ) ) : ?><div class="discovery-grid"><?php foreach ( $result['items'] as $skill ) { get_template_part( 'templates/discovery/skill', null, array( 'skill' => $skill, 'locale' => $locale ) ); } ?></div><?php else : ?><div class="discovery-empty"><h2><?php echo esc_html( Discovery::t( 'empty', $locale ) ); ?></h2><p><?php echo esc_html( Discovery::t( 'empty-help', $locale ) ); ?></p></div><?php endif; ?>
			<?php echo Discovery::pagination( $result, $route, $locale, array_merge( $filters, array_filter( $params ) ) ); ?>
			<?php if ( ! empty( $result['limited_samples']['items'] ) ) : ?><section class="discovery-module"><h2><?php echo esc_html( Discovery::t( 'limited-sample', $locale ) ); ?></h2><p class="discovery-filter-note"><?php echo esc_html( 'zh_CN' === $locale ? '以下为真实评分和评价数量，尚未达到正式排名的最低样本数量。' : 'These actual ratings have not yet reached the minimum review count for ranking.' ); ?></p><div class="discovery-grid"><?php foreach ( $result['limited_samples']['items'] as $skill ) { get_template_part( 'templates/discovery/skill', null, array( 'skill' => $skill, 'locale' => $locale ) ); } ?></div></section><?php endif; ?>
			<?php if ( ! empty( $data['tutorials'] ) ) : ?><section class="discovery-module"><h2><?php echo esc_html( Discovery::t( 'tutorials', $locale ) ); ?></h2><div class="skill-grid"><?php foreach ( $data['tutorials'] as $tutorial ) { get_template_part( 'template-parts/frontend/tutorial-card', null, array( 'tutorial' => $tutorial ) ); } ?></div></section><?php endif; ?>
		<?php endif; ?>
	<?php endif; ?>
</div>
</main>
<?php get_footer(); ?>
